IF NOT Enable THEN
    internalPhase := 0;
    age := 0;
ELSIF Tick THEN
    CASE internalPhase OF
        0:
            age := age + 1;
            IF age >= 2 THEN
                internalPhase := 1;
                age := 0;
            END_IF;
        1:
            age := age + 1;
            IF age >= 3 THEN
                internalPhase := 2;
                age := 0;
            END_IF;
